+{"connection_id":"BC-7350c7aacd82b70bdd65","ref":"SBLGNT:2Cor.6.16","status":"rejected","reason":"Mabed ile putlar karşılaştırılır; fiziksel yandan uzaklaşma ve İbrahim'in ailesi bu ayette yer almaz.","paragraphs":[57],"evidence":["SBLGNT:2Cor.6.16"],"annotations":[]}
+{"connection_id":"BC-8f4ccddbf5830e5b6023","ref":"SBLGNT:2Cor.6.17","status":"rejected","reason":"Ayrılma buyruğu somuttur fakat muhatap cemaatin kirli çevresidir; 14:35'teki İbrahim duasının aile ve put nesnesini vermez.","paragraphs":[57],"evidence":["SBLGNT:2Cor.6.17"],"annotations":[]}
